package com.proyecto.agendaty.mapper;import com.proyecto.agendaty.dto.AsesorRequest;import com.proyecto.agendaty.dto.AsesorResponse;import com.proyecto.agendaty.dto.AtencionResponse;import com.proyecto.agendaty.dto.CiudadanoRequest;import com.proyecto.agendaty.dto.CiudadanoResponse;import com.proyecto.agendaty.dto.TipoTramiteRequest;import com.proyecto.agendaty.dto.TipoTramiteResponse;import com.proyecto.agendaty.dto.TurnoRequest;import com.proyecto.agendaty.dto.TurnoResponse;import com.proyecto.agendaty.dto.VentanillaRequest;import com.proyecto.agendaty.dto.VentanillaResponse;import com.proyecto.agendaty.entity.Asesor;import com.proyecto.agendaty.entity.Atencion;import com.proyecto.agendaty.entity.Ciudadano;import com.proyecto.agendaty.entity.TipoTramite;import com.proyecto.agendaty.entity.Turno;import com.proyecto.agendaty.entity.Ventanilla;import com.proyecto.agendaty.model.enums.EstadoTurno;import com.proyecto.agendaty.model.enums.PrioridadTurno;import org.junit.jupiter.api.Test;import java.time.LocalDateTime;import java.util.List;import static org.junit.jupiter.api.Assertions.*;class MappersTest {    private final AtencionMapper atencionMapper = new AtencionMapper();    private final AsesorMapper asesorMapper = new AsesorMapper();    private final CiudadanoMapper ciudadanoMapper = new CiudadanoMapper();    private final TipoTramiteMapper tipoTramiteMapper = new TipoTramiteMapper();    private final TurnoMapper turnoMapper = new TurnoMapper();    private final VentanillaMapper ventanillaMapper = new VentanillaMapper();    private Ciudadano crearCiudadano() {        Ciudadano c = new Ciudadano();        c.setId(1);        c.setNombre("Juan Pérez");        c.setCorreo("juan@email.com");        c.setDocumento("12345678");        c.setTelefono("3001234567");        return c;    }    private Asesor crearAsesor() {        Asesor a = new Asesor();        a.setId(7);        a.setNombre("Asesor Uno");        a.setDisponible(true);        a.setCorreo("asesor@turnos.local");        a.setPassword("hash");        a.setUsername("asesor@turnos.local");        return a;    }    private TipoTramite crearTipoTramite() {        TipoTramite t = new TipoTramite();        t.setId(3L);        t.setNombre("Cédula de Identidad");        t.setCodigo("CED");        t.setEsPrioritarioPorDefecto(false);        t.setActivo(true);        return t;    }    /* ==================== AtencionMapper ==================== */    @Test    void atencionMapper_nullDevuelveNull() {        assertNull(atencionMapper.toResponse(null));    }    @Test    void atencionMapper_conDatosCompletos() {        Turno turno = new Turno();        turno.setId(10L);        turno.setNumeroTurno("CEDN-00001");        Asesor asesor = crearAsesor();        Atencion a = new Atencion();        a.setId(99L);        a.setTurno(turno);        a.setAsesor(asesor);        a.setFechaInicio(LocalDateTime.of(2026, 11, 15, 9, 0));        a.setFechaFin(LocalDateTime.of(2026, 11, 15, 9, 30));        a.setObservaciones("OK");        a.setResultado("Cédula expedida");        a.setTiempoEsperaMinutos(5);        a.setTiempoAtencionMinutos(25);        a.setTotalPausasMinutos(2);        AtencionResponse r = atencionMapper.toResponse(a);        assertEquals(99L, r.id());        assertEquals(10L, r.turnoId());        assertEquals("CEDN-00001", r.numeroTurno());        assertEquals(7, r.asesorId());        assertEquals("Asesor Uno", r.asesorNombre());        assertEquals(LocalDateTime.of(2026, 11, 15, 9, 0), r.fechaInicio());        assertEquals(LocalDateTime.of(2026, 11, 15, 9, 30), r.fechaFin());        assertEquals("OK", r.observaciones());        assertEquals("Cédula expedida", r.resultado());        assertEquals(5, r.tiempoEsperaMinutos());        assertEquals(25, r.tiempoAtencionMinutos());        assertEquals(2, r.totalPausasMinutos());    }    @Test    void atencionMapper_sinTurnoNiAsesor() {        Atencion a = new Atencion();        a.setId(1L);        AtencionResponse r = atencionMapper.toResponse(a);        assertEquals(1L, r.id());        assertNull(r.turnoId());        assertNull(r.numeroTurno());        assertNull(r.asesorId());        assertNull(r.asesorNombre());    }    /* ==================== CiudadanoMapper ==================== */    @Test    void ciudadanoMapper_toEntity() {        CiudadanoRequest req = new CiudadanoRequest("Juan", "juan@email.com", "12345678", "3001234567");        Ciudadano c = ciudadanoMapper.toEntity(req);        assertEquals("Juan", c.getNombre());        assertEquals("juan@email.com", c.getCorreo());        assertEquals("12345678", c.getDocumento());        assertEquals("3001234567", c.getTelefono());    }    @Test    void ciudadanoMapper_toResponse() {        Ciudadano c = crearCiudadano();        CiudadanoResponse r = ciudadanoMapper.toResponse(c);        assertEquals(1, r.id());        assertEquals("Juan Pérez", r.nombre());        assertEquals("juan@email.com", r.correo());        assertEquals("12345678", r.documento());        assertEquals("3001234567", r.telefono());    }    /* ==================== TipoTramiteMapper ==================== */    @Test    void tipoTramiteMapper_nullRequestDevuelveNull() {        assertNull(tipoTramiteMapper.toEntity(null));    }    @Test    void tipoTramiteMapper_nullTipoDevuelveNull() {        assertNull(tipoTramiteMapper.toResponse(null));    }    @Test    void tipoTramiteMapper_aplicaDefaults() {        TipoTramiteRequest req = new TipoTramiteRequest("Nombre", "COD", null, null);        TipoTramite t = tipoTramiteMapper.toEntity(req);        assertEquals(false, t.getEsPrioritarioPorDefecto());        assertEquals(true, t.getActivo());    }    @Test    void tipoTramiteMapper_respetaValoresExplicitos() {        TipoTramiteRequest req = new TipoTramiteRequest("Nombre", "COD", true, false);        TipoTramite t = tipoTramiteMapper.toEntity(req);        assertEquals(true, t.getEsPrioritarioPorDefecto());        assertEquals(false, t.getActivo());    }    @Test    void tipoTramiteMapper_toResponse() {        TipoTramite t = crearTipoTramite();        TipoTramiteResponse r = tipoTramiteMapper.toResponse(t);        assertEquals(3L, r.id());        assertEquals("Cédula de Identidad", r.nombre());        assertEquals("CED", r.codigo());        assertEquals(false, r.esPrioritarioPorDefecto());        assertEquals(true, r.activo());    }    /* ==================== TurnoMapper ==================== */    @Test    void turnoMapper_nullRequestDevuelveNull() {        assertNull(turnoMapper.toEntity(null));    }    @Test    void turnoMapper_toEntityPrioritario() {        TurnoRequest req = new TurnoRequest(5, 1L, true);        Turno t = turnoMapper.toEntity(req);        assertEquals(PrioridadTurno.PRIORITARIO, t.getPrioridad());    }    @Test    void turnoMapper_toEntityNormal() {        TurnoRequest req = new TurnoRequest(5, 1L, false);        Turno t = turnoMapper.toEntity(req);        assertEquals(PrioridadTurno.NORMAL, t.getPrioridad());    }    @Test    void turnoMapper_toEntityPrioritarioNull() {        TurnoRequest req = new TurnoRequest(5, 1L, null);        Turno t = turnoMapper.toEntity(req);        assertEquals(PrioridadTurno.NORMAL, t.getPrioridad());    }    @Test    void turnoMapper_toResponseNullDevuelveNull() {        assertNull(turnoMapper.toResponse(null));    }    @Test    void turnoMapper_toResponseConDatosCompletos() {        Ciudadano c = crearCiudadano();        TipoTramite tipo = crearTipoTramite();        Asesor asesor = crearAsesor();        Turno t = new Turno();        t.setId(100L);        t.setNumeroTurno("CEDN-00001");        t.setEstado(EstadoTurno.EN_ATENCION);        t.setPrioridad(PrioridadTurno.PRIORITARIO);        t.setFechaCreacion(LocalDateTime.of(2026, 11, 15, 8, 0));        t.setFechaLlamado(LocalDateTime.of(2026, 11, 15, 8, 15));        t.setFechaFinEspera(LocalDateTime.of(2026, 11, 15, 9, 0));        t.setCiudadano(c);        t.setTipoTramite(tipo);        t.setAsesor(asesor);        TurnoResponse r = turnoMapper.toResponse(t);        assertEquals(100L, r.id());        assertEquals("CEDN-00001", r.numeroTurno());        assertEquals(EstadoTurno.EN_ATENCION, r.estado());        assertEquals(PrioridadTurno.PRIORITARIO, r.prioridad());        assertEquals(LocalDateTime.of(2026, 11, 15, 8, 0), r.fechaCreacion());        assertEquals(LocalDateTime.of(2026, 11, 15, 8, 15), r.fechaLlamado());        assertEquals(LocalDateTime.of(2026, 11, 15, 9, 0), r.fechaFinEspera());        assertEquals(1, r.ciudadanoId());        assertEquals("Juan Pérez", r.ciudadanoNombre());        assertEquals(3L, r.tipoTramiteId());        assertEquals("Cédula de Identidad", r.tipoTramiteNombre());        assertEquals(7, r.asesorId());        assertEquals("Asesor Uno", r.asesorNombre());    }    @Test    void turnoMapper_toResponseSinRelaciones() {        Turno t = new Turno();        t.setId(1L);        t.setNumeroTurno("X");        t.setEstado(EstadoTurno.EN_ESPERA);        t.setPrioridad(PrioridadTurno.NORMAL);        TurnoResponse r = turnoMapper.toResponse(t);        assertEquals(1L, r.id());        assertNull(r.ciudadanoId());        assertNull(r.ciudadanoNombre());        assertNull(r.tipoTramiteId());        assertNull(r.tipoTramiteNombre());        assertNull(r.asesorId());        assertNull(r.asesorNombre());    }    /* ==================== AsesorMapper ==================== */    @Test    void asesorMapper_toResponseNullDevuelveNull() {        assertNull(asesorMapper.toResponse(null));    }    @Test    void asesorMapper_toResponseConVentanilla() {        Asesor a = crearAsesor();        Ventanilla v = new Ventanilla();        v.setNumero(5);        a.setVentanillaActual(v);        AsesorResponse r = asesorMapper.toResponse(a);        assertEquals(7, r.getId());        assertEquals("Asesor Uno", r.getNombre());        assertEquals(true, r.getDisponible());        assertEquals(5, r.getNumeroVentanilla());    }    @Test    void asesorMapper_toEntityNullDevuelveNull() {        assertNull(asesorMapper.toEntity(null));    }    @Test    void asesorMapper_toEntity() {        AsesorRequest req = new AsesorRequest();        req.setNombre("María");        Asesor a = asesorMapper.toEntity(req);        assertEquals("María", a.getNombre());    }    /* ==================== VentanillaMapper ==================== */    @Test    void ventanillaMapper_toResponseNullDevuelveNull() {        assertNull(ventanillaMapper.toResponse(null));    }    @Test    void ventanillaMapper_toResponseConAsesor() {        Ventanilla v = new Ventanilla();        v.setId(2L);        v.setNumero(7);        v.setDescripcion("Atención prioritaria");        Asesor a = crearAsesor();        v.setAsesorActual(a);        VentanillaResponse r = ventanillaMapper.toResponse(v);        assertEquals(2L, r.getId());        assertEquals(7, r.getNumero());        assertEquals("Atención prioritaria", r.getDescripcion());        assertEquals(7, r.getAsesorId());    }    @Test    void ventanillaMapper_toResponseSinAsesor() {        Ventanilla v = new Ventanilla();        v.setId(3L);        v.setNumero(9);        v.setDescripcion("Sin asesor");        VentanillaResponse r = ventanillaMapper.toResponse(v);        assertNull(r.getAsesorId());    }    @Test    void ventanillaMapper_toEntity() {        VentanillaRequest req = new VentanillaRequest();        req.setNumero(4);        req.setDescripcion("Test");        Ventanilla v = ventanillaMapper.toEntity(req);        assertEquals(4, v.getNumero());        assertEquals("Test", v.getDescripcion());    }    @Test    void ventanillaMapper_toListResponseNullDevuelveListaVacia() {        assertTrue(ventanillaMapper.toListResponse(null).isEmpty());    }    @Test    void ventanillaMapper_toListResponseConElementos() {        Ventanilla v1 = new Ventanilla();        v1.setId(1L);        v1.setNumero(1);        Asesor a = crearAsesor();        v1.setAsesorActual(a);        Ventanilla v2 = new Ventanilla();        v2.setId(2L);        v2.setNumero(2);        List<VentanillaResponse> lista = ventanillaMapper.toListResponse(List.of(v1, v2));        assertEquals(2, lista.size());        assertEquals(7, lista.get(0).getAsesorId());        assertNull(lista.get(1).getAsesorId());    }}